const items = [];
for (let r = 0; r < 500; r++) { let a; try { a = $('Tag Source').all(0, r); } catch (e) { break; } if (!a) break; items.push(...a); }
const cutoff = Date.now() - 72 * 3600e3;
const seen = {};
const out = [];
function norm(s){return String(s||'').toLowerCase().replace(/[ً-ْـ]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[^\p{L}\p{N} ]+/gu,' ').replace(/\s+/g,' ').trim();}
function h(s){let x=5381;for(let i=0;i<s.length;i++){x=((x<<5)+x+s.charCodeAt(i))|0;}return (x>>>0).toString(36);}
for (const it of items) {
  const j = it.json || {};
  if (j._empty || j.error || !j.title) continue;
  const src = j._src || {};
  let title = String(j.title).trim();
  const dash = title.lastIndexOf(' - ');
  const publisher = dash > 10 ? title.slice(dash + 3).trim() : '';
  if (dash > 10) title = title.slice(0, dash).trim();
  const pub = j.isoDate || j.pubDate || '';
  const t = pub ? new Date(pub).getTime() : Date.now();
  if (isNaN(t) || t < cutoff) continue;
  const words = norm(title).split(' ').filter(w => w.length > 1);
  const key = words.slice(0, 8).join(' ');
  if (!key || seen[key]) continue;
  seen[key] = 1;
  out.push({ json: {
    dedupe_key: key,
    news_id: 'NEWS-' + new Date(t).toISOString().slice(0,10).replace(/-/g,'') + '-' + h(key),
    title, publisher,
    snippet: String(j.contentSnippet || j.content || '').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0, 400),
    url: j.link || '',
    published_at: new Date(t).toISOString(),
    source_name: src.source_name || '', authority: src.authority || '', sector: src.sector || '', owner_agent: src.owner_agent || '', priority: src.priority || ''
  } });
}
out.sort((a,b) => (a.json.published_at < b.json.published_at ? 1 : -1));
return out.slice(0, 80);

const known = {};
for (const it of $('Read Known News').all()) { const k = it.json && it.json.dedupe_key; if (k) known[k] = 1; }
const out = [];
for (const it of $('Normalize Candidates').all()) { const j = it.json; if (j && j.dedupe_key && !known[j.dedupe_key]) out.push({ json: j }); }
return out.slice(0, 25);

const cands = $('Only New').all().map(i => i.json);
const first = ($input.first() && $input.first().json) || {};
let parsed = null;
if (first && Array.isArray(first.items)) parsed = first;
else {
  const raw = first.text || first.output || '';
  if (raw && typeof raw === 'object') parsed = raw;
  else { try { parsed = JSON.parse(String(raw).replace(/```json/gi,'').replace(/```/g,'').trim()); } catch (e) { parsed = null; } }
}
const byI = {}; if (parsed && Array.isArray(parsed.items)) for (const x of parsed.items) byI[Number(x.i)] = x;
const now = new Date().toISOString();
const lv = { Low: 1, Medium: 2, High: 3, Critical: 4 };
return cands.map((c, i) => { const x = byI[i] || {}; const impact = lv[x.impact_level] ? x.impact_level : 'Low'; const relevant = x.relevant === true;
  return { json: { ...c, relevant, impact_level: relevant ? impact : 'Low', category: String(x.category || ''), affected_audience: Array.isArray(x.affected_audience) ? x.affected_audience.join(', ') : String(x.affected_audience || ''),
    summary_ar: String(x.summary_ar || c.snippet || c.title).slice(0, 500), required_action: String(x.required_action || '').slice(0, 400), business_opportunity: String(x.business_opportunity || '').slice(0, 400), recommended_service: String(x.recommended_service || ''),
    is_sales_opportunity: x.is_sales_opportunity === true, is_content_worthy: x.is_content_worthy === true, status: 'new', fetched_at: now, classified: !!parsed } }; });

