const rows = $('Urgent?').all(0).map(i => i.json);
if (!rows.length) return [];
const stamp = new Date().toLocaleTimeString('ar-SA', { timeZone: 'Asia/Riyadh', hour: '2-digit', minute: '2-digit' });
const lines = rows.slice(0, 6).map(r => {
  const icon = r.impact_level === 'Critical' ? '🔴' : '🟠';
  return icon + ' ' + r.title + '
' + (r.summary_ar || '') + (r.required_action ? '
↳ الإجراء: ' + r.required_action : '') + '
المصدر: ' + r.source_name + ' · ' + r.url;
});
const text = 'آلاء — تحديث حكومي مهم ' + stamp + '

' + lines.join('

') + (rows.length > 6 ? '

…و' + (rows.length - 6) + ' أخرى في الموجز الصباحي.' : '') + '

كلّفتُ مشاري بالتحقق من المصدر الرسمي وتقدير الأثر، وسيستشير آلاء وبدر. اسأل فرح «وش جديد الجهات؟» للتفاصيل.';
return [{ json: { text: text.slice(0, 4000) } }];

const all = $input.all().map(i => i.json).filter(r => r && r.title);
const rows = all.filter(r => r.relevant === true);
const lv = { Critical: 4, High: 3, Medium: 2, Low: 1 };
rows.sort((a, b) => (lv[b.impact_level] || 0) - (lv[a.impact_level] || 0) || String(b.published_at).localeCompare(String(a.published_at)));
const date = new Date().toLocaleDateString('ar-SA', { timeZone: 'Asia/Riyadh', day: 'numeric', month: 'long' });
if (!rows.length) return [{ json: { text: '📰 آلاء — الموجز الأسبوعي للجهات الحكومية · أسبوع ' + date + '

لا تحديثات تنظيمية مؤثرة هذا الأسبوع (' + all.length + ' خبراً فُحص واستُبعد).' } }];
const icon = l => l === 'Critical' ? '🔴' : l === 'High' ? '🟠' : l === 'Medium' ? '🟡' : '⚪';
const top = rows.slice(0, 10);
const lines = top.map((r, i) => (i + 1) + '. ' + icon(r.impact_level) + ' ' + r.title + '
' + (r.summary_ar || '').slice(0, 200) + (r.recommended_service ? '
↳ خدمتنا: ' + r.recommended_service : '') + '
' + r.url);
const crit = rows.filter(r => r.impact_level === 'Critical').length, high = rows.filter(r => r.impact_level === 'High').length;
const text = '📰 آلاء — الموجز الأسبوعي للجهات الحكومية · أسبوع ' + date + '
' + rows.length + ' تحديثاً مؤثراً من ' + all.length + ' خبراً فُحص (' + crit + ' حرج، ' + high + ' مرتفع). الفريق اشتغل على المرتفع خلال الأسبوع (مشاري يتحقق، آلاء تصيغ، بدر يلتقط الفرص).

' + lines.join('

') + (rows.length > 10 ? '

…و' + (rows.length - 10) + ' أخرى عند فرح — اسألها «وش جديد الجهات؟».' : '') + '

للنشر على الموقع: ردّ برقم الخبر.';
return [{ json: { text: text.slice(0, 4000) } }];

const src = $('Loop Sources').first().json || {};
const tag = { source_name: src.source_name || '', authority: src.authority || '', sector: src.sector || '', owner_agent: src.owner_agent || '', priority: src.priority || '' };
const out = $input.all().filter(it => it.json && !it.json.error && it.json.title).map(it => ({ json: { ...it.json, _src: tag } }));
return out.length ? out : [{ json: { _empty: true, _src: tag } }];
